#define _GNU_SOURCE
#include <dlfcn.h>
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static ssize_t (*real_read)(int, void*, size_t);
static const char* target;
static long fail_after;
static long seen;

static void init(void) {
    if (!real_read) {
        real_read = dlsym(RTLD_NEXT, "read");
        target = getenv("SHIM_PATH");
        const char* n = getenv("SHIM_FAIL_AFTER");
        fail_after = n ? atol(n) : 0;
    }
}

ssize_t read(int fd, void* buf, size_t count) {
    init();
    if (target) {
        char link[64], path[4096];
        snprintf(link, sizeof link, "/proc/self/fd/%d", fd);
        ssize_t len = readlink(link, path, sizeof path - 1);
        if (len > 0) {
            path[len] = 0;
            if (strcmp(path, target) == 0) {
                if (seen >= fail_after) {
                    errno = EIO;
                    return -1;
                }
                if ((long)count > fail_after - seen)
                    count = (size_t)(fail_after - seen);
                ssize_t r = real_read(fd, buf, count);
                if (r > 0) seen += r;
                return r;
            }
        }
    }
    return real_read(fd, buf, count);
}

